def main():
    print(f"Total Chapters to process: {len(CHAPTERS)}")
    
    # 1. Build TypeScript file content
    ts_content = "import { Question } from '../types';\n\n"
    all_questions_list = []
    
    q_counter = 1
    for ch_title, unit, vol, q_list in CHAPTERS:
        var_name = re.sub(r'[^a-zA-Z0-9]', '_', ch_title).upper() + f"_V{vol}_QUESTIONS"
        ts_content += f"// {unit} - {ch_title} (Vol {vol})\n"
        ts_content += f"export const {var_name}: Question[] = [\n"
        
        for q_text, opts, ans_idx, exp in q_list:
            q_id = f"bio-v{vol}-c{ch_title.lower().replace(' ', '-')[:15]}-q{q_counter}"
            q_obj = {
                "id": q_id,
                "subject": "Biology",
                "chapter": ch_title,
                "topic": unit,
                "difficulty": "Medium",
                "questionText": q_text,
                "options": opts,
                "correctAnswer": ans_idx,
                "explanation": exp,
                "pyqYear": 2023,
                "tags": [unit, ch_title, f"Class {11 if vol==1 else 12}"]
            }
            all_questions_list.append(q_obj)
            
            opts_str = json.dumps(opts)
            exp_clean = exp.replace('"', '\\"')
            q_text_clean = q_text.replace('"', '\\"')
            
            ts_content += f"  {{\n"
            ts_content += f'    id: "{q_id}",\n'
            ts_content += f'    subject: "Biology",\n'
            ts_content += f'    chapter: "{ch_title}",\n'
            ts_content += f'    topic: "{unit}",\n'
            ts_content += f'    difficulty: "Medium",\n'
            ts_content += f'    questionText: "{q_text_clean}",\n'
            ts_content += f'    options: {opts_str},\n'
            ts_content += f'    correctAnswer: {ans_idx},\n'
            ts_content += f'    explanation: "{exp_clean}",\n'
            ts_content += f'    pyqYear: 2023,\n'
            ts_content += f'    tags: ["{unit}", "{ch_title}", "Class {11 if vol==1 else 12}"]\n'
            ts_content += f"  }},\n"
            q_counter += 1
            
        ts_content += "];\n\n"
        
    ts_content += "// Combined Full 380 Questions NEET Biology Master Collection\n"
    ts_content += "export const ALL_BIOLOGY_MASTER_QUESTIONS: Question[] = [\n"
    for ch_title, unit, vol, q_list in CHAPTERS:
        var_name = re.sub(r'[^a-zA-Z0-9]', '_', ch_title).upper() + f"_V{vol}_QUESTIONS"
        ts_content += f"  ...{var_name},\n"
    ts_content += "];\n"
    
    # Write to src/data/biologyQuestions.ts
    target_ts_file = r"C:\Users\aditi\OneDrive\Desktop\neet_jee-prep-platform\src\data\biologyQuestions.ts"
    with open(target_ts_file, "w", encoding="utf-8") as f:
        f.write(ts_content)
    print(f"Successfully generated {target_ts_file} with {len(all_questions_list)} questions!")
    
    # 2. Upload to Supabase
    print("Uploading all 380 questions to Supabase in batches of 50...")
    upload_url = f"{SUPABASE_URL}/rest/v1/questions"
    
    db_payload = []
    for q in all_questions_list:
        db_payload.append({
            "id": q["id"],
            "subject": q["subject"],
            "chapter": q["chapter"],
            "topic": q["topic"],
            "difficulty": q["difficulty"],
            "question_text": q["questionText"],
            "options": q["options"],
            "correct_answer": q["correctAnswer"],
            "explanation": q["explanation"]
        })
        
    batch_size = 50
    for i in range(0, len(db_payload), batch_size):
        batch = db_payload[i:i+batch_size]
        payload_bytes = json.dumps(batch).encode("utf-8")
        req = urllib.request.Request(
            upload_url,
            data=payload_bytes,
            headers={
                "apikey": ANON_KEY,
                "Authorization": f"Bearer {ANON_KEY}",
                "Content-Type": "application/json",
                "Prefer": "resolution=merge-duplicates"
            },
            method="POST"
        )
        try:
            with urllib.request.urlopen(req) as resp:
                print(f"Uploaded Supabase batch {i//batch_size + 1}/{(len(db_payload)-1)//batch_size + 1} ({len(batch)} questions)")
        except urllib.error.HTTPError as e:
            print(f"Supabase HTTP Error on batch {i}: {e.code} - {e.read().decode('utf-8')}")
        except Exception as e:
            print(f"Supabase Error on batch {i}: {e}")

if __name__ == "__main__":
    main()
